-- v3 (D-13) L1 replay, Payoneer proxy keys, sessions created 2026-11-18 10:00-14:00 UTC, no sampling. Identical to v2 10_replay_L1_payoneer_v2.sql
-- (window, List A/B only, thresholds g = v2's per-key matrix) except EE844FC3 Dict 1 cells take the variant value from 03c_:
--   V0/V1: Mobile 12.0/720, other groups 12.1/726 (= v2);  V2/V3: Mobile 25.22/1513.2, other groups 25.81/1548.6.
-- E3EFEFBF / 7CC24C4A Dict 1 cells are (b) = today's threshold in every variant. NON-DICT-1 CELLS ARE KEPT AT V0 (v2) VALUES for every
-- variant: an upper bound for V1-V3 (their thresholds are >= V0), and those cells carried ~27 of v2's 113,595 fires.
-- Output: v|key|n|T(today ST)|NA n/High%/ver%|NA_d1|NA_other
WITH g(k,d,grp,tst,tlt) AS (SELECT * FROM VALUES ('EE844FC3',-1,'Desktop',35,2100),('EE844FC3',-1,'Mobile',35,2100),('EE844FC3',-1,'Linux',35,2100),('EE844FC3',-1,'WinRDVM',35,2100),('EE844FC3',-1,'Other',35,2100),('EE844FC3',1,'Desktop',12.1,726.0),('EE844FC3',1,'Mobile',12.0,720.0),('EE844FC3',1,'Linux',12.1,726.0),('EE844FC3',1,'WinRDVM',12.1,726.0),('EE844FC3',1,'Other',12.1,726.0),('EE844FC3',3,'Desktop',231.0,13860.0),('EE844FC3',3,'Mobile',115.0,6900.0),('EE844FC3',3,'Linux',35,2100),('EE844FC3',3,'WinRDVM',35,2100),('EE844FC3',3,'Other',35,2100),('EE844FC3',7,'Desktop',73.5,5880.0),('EE844FC3',7,'Mobile',15.0,1200.0),('EE844FC3',7,'Linux',25.05,2004.0),('EE844FC3',7,'WinRDVM',18.0,1440.0),('EE844FC3',7,'Other',35,2100),('EE844FC3',15,'Desktop',24.0,2880.0),('EE844FC3',15,'Mobile',106.0,12720.0),('EE844FC3',15,'Linux',22.0,2640.0),('EE844FC3',15,'WinRDVM',13.35,1068.0),('EE844FC3',15,'Other',35,2100),('EE844FC3',31,'Desktop',38.0,4560.0),('EE844FC3',31,'Mobile',28.0,3360.0),('EE844FC3',31,'Linux',27.0,3240.0),('EE844FC3',31,'WinRDVM',12.0,960.0),('EE844FC3',31,'Other',35,2100),('EE844FC3',63,'Desktop',30.0,5400.0),('EE844FC3',63,'Mobile',297.4,53532.0),('EE844FC3',63,'Linux',16.8,3024.0),('EE844FC3',63,'WinRDVM',18.0,1440.0),('EE844FC3',63,'Other',35,2100),('E3EFEFBF',-1,'Desktop',15,900),('E3EFEFBF',-1,'Mobile',15,900),('E3EFEFBF',-1,'Linux',15,900),('E3EFEFBF',-1,'WinRDVM',15,900),('E3EFEFBF',-1,'Other',15,900),('E3EFEFBF',1,'Desktop',15,900),('E3EFEFBF',1,'Mobile',15,900),('E3EFEFBF',1,'Linux',15,900),('E3EFEFBF',1,'WinRDVM',15,900),('E3EFEFBF',1,'Other',15,900),('E3EFEFBF',3,'Desktop',35.0,2100.0),('E3EFEFBF',3,'Mobile',80.0,4800.0),('E3EFEFBF',3,'Linux',15,900),('E3EFEFBF',3,'WinRDVM',15,900),('E3EFEFBF',3,'Other',15,900),('E3EFEFBF',7,'Desktop',22.5,1800.0),('E3EFEFBF',7,'Mobile',15.0,1200.0),('E3EFEFBF',7,'Linux',15.0,1200.0),('E3EFEFBF',7,'WinRDVM',10.5,840.0),('E3EFEFBF',7,'Other',15,900),('E3EFEFBF',15,'Desktop',16.0,1920.0),('E3EFEFBF',15,'Mobile',32.0,3840.0),('E3EFEFBF',15,'Linux',18.0,2160.0),('E3EFEFBF',15,'WinRDVM',10.5,840.0),('E3EFEFBF',15,'Other',15,900),('E3EFEFBF',31,'Desktop',19.4,2328.0),('E3EFEFBF',31,'Mobile',24.0,2880.0),('E3EFEFBF',31,'Linux',15,900),('E3EFEFBF',31,'WinRDVM',10.5,840.0),('E3EFEFBF',31,'Other',15,900),('E3EFEFBF',63,'Desktop',20.0,3600.0),('E3EFEFBF',63,'Mobile',46.0,8280.0),('E3EFEFBF',63,'Linux',15,900),('E3EFEFBF',63,'WinRDVM',12.6,1008.0),('E3EFEFBF',63,'Other',15,900),('7CC24C4A',-1,'Desktop',60,3600),('7CC24C4A',-1,'Mobile',60,3600),('7CC24C4A',-1,'Linux',60,3600),('7CC24C4A',-1,'WinRDVM',60,3600),('7CC24C4A',-1,'Other',60,3600),('7CC24C4A',1,'Desktop',60,3600),('7CC24C4A',1,'Mobile',60,3600),('7CC24C4A',1,'Linux',60,3600),('7CC24C4A',1,'WinRDVM',60,3600),('7CC24C4A',1,'Other',60,3600),('7CC24C4A',3,'Desktop',12.9,774.0),('7CC24C4A',3,'Mobile',27.0,1620.0),('7CC24C4A',3,'Linux',27.0,1620.0),('7CC24C4A',3,'WinRDVM',27.0,1620.0),('7CC24C4A',3,'Other',27.0,1620.0),('7CC24C4A',7,'Desktop',13.5,1080.0),('7CC24C4A',7,'Mobile',10.8,864.0),('7CC24C4A',7,'Linux',13.5,1080.0),('7CC24C4A',7,'WinRDVM',13.5,1080.0),('7CC24C4A',7,'Other',13.5,1080.0),('7CC24C4A',15,'Desktop',14.0,1680.0),('7CC24C4A',15,'Mobile',18.0,2160.0),('7CC24C4A',15,'Linux',16.6,1992.0),('7CC24C4A',15,'WinRDVM',12.45,996.0),('7CC24C4A',15,'Other',16.6,1992.0),('7CC24C4A',31,'Desktop',16.0,1920.0),('7CC24C4A',31,'Mobile',20.0,2400.0),('7CC24C4A',31,'Linux',16.0,1920.0),('7CC24C4A',31,'WinRDVM',12.0,960.0),('7CC24C4A',31,'Other',16.0,1920.0),('7CC24C4A',63,'Desktop',14.0,2520.0),('7CC24C4A',63,'Mobile',24.0,4320.0),('7CC24C4A',63,'Linux',22.0,3600),('7CC24C4A',63,'WinRDVM',16.5,1320.0),('7CC24C4A',63,'Other',22.0,3600)),
s0 AS (SELECT LEFT(public_key,8) k, di_dictionary_num_matched_at_session_created d, os_at_session_created os, COALESCE(webgl_unmasked_renderer_at_session_created,'') r, IFF(latest_risk_band='High',1,0) hi, IFF(sessions_verified>0,1,0) ver, di_short_term_count_at_session_created stc, di_long_term_count_at_session_created ltc, IFF(di_short_term_threshold_breached_at_session_created,1,0) stb FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key IN ('EE844FC3-499D-4A4D-A643-D7400F0FD4DE','E3EFEFBF-8DE4-42ED-9E7F-92F35B1FD3CF','7CC24C4A-611B-41C7-9808-B95722C7861C') AND session_last_timestamp>='2026-11-18 10:00' AND session_last_timestamp<'2026-11-18 20:00' AND session_ts>='2026-11-18 10:00' AND session_ts<'2026-11-18 14:00' AND di_dictionary_num_matched_at_session_created IS NOT NULL),
s1 AS (SELECT s0.*, CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A' WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B' END AS x, CASE WHEN r ILIKE '%Basic Render Driver%' AND os='Windows' THEN 'WinRDVM' WHEN os IN ('Windows','OS X','Chrome OS') THEN 'Desktop' WHEN os IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN os IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS grp FROM s0),
f AS (SELECT s1.*, v.column1 v,
  IFF(s1.k='EE844FC3' AND s1.d=1 AND v.column1>=2, IFF(s1.grp='Mobile',25.22,25.81), g.tst) st,
  IFF(s1.k='EE844FC3' AND s1.d=1 AND v.column1>=2, IFF(s1.grp='Mobile',1513.2,1548.6), g.tlt) lt
  FROM s1 LEFT JOIN g ON g.k=s1.k AND g.d=s1.d AND g.grp=s1.grp CROSS JOIN (SELECT column1 FROM VALUES (0),(1),(2),(3)) v),
h AS (SELECT f.*, IFF(x IS NULL AND (stc>st OR ltc>lt),1,0) na FROM f)
SELECT v||'|'||COALESCE(k,'ALL')||'|n='||COUNT(*)||'|T='||SUM(stb)||'|NA='||SUM(na)||'/'||ROUND(100*SUM(na*hi)/NULLIF(SUM(na),0),1)||'/'||ROUND(100*SUM(na*ver)/NULLIF(SUM(na),0),1)
  ||'|NA_d1='||SUM(IFF(d=1,na,0))||'|NA_other='||SUM(IFF(d<>1,na,0))||'|n_d1='||SUM(IFF(d=1,1,0)) r
FROM h GROUP BY GROUPING SETS ((v,k),(v)) ORDER BY v, k;
